import subprocess
from pathlib import Path
from langchain_core.tools import tool

RNDC_BINARY_PATH = "/usr/sbin/rndc"
DEFAULT_ZONE_DIRECTORY = "/var/named/dynamic"


def _normalize_zone_name(raw_zone_name: str) -> str:
    stripped_zone_name = raw_zone_name.strip().lower()
    if not stripped_zone_name:
        raise ValueError("zone_name must not be empty")
    return stripped_zone_name.rstrip(".")


@tool
def remove_authoritative_zone(zone_name: str, view_name: str = None, zone_directory: str = None) -> dict:
    normalized_zone_name = _normalize_zone_name(zone_name)
    resolved_zone_directory = Path(zone_directory or DEFAULT_ZONE_DIRECTORY)

    rndc_target_argument = normalized_zone_name
    if view_name:
        rndc_target_argument = f"{normalized_zone_name} IN {view_name}"

    rndc_command_arguments = [RNDC_BINARY_PATH, "delzone", "-clean"] + rndc_target_argument.split()
    completed_rndc_process = subprocess.run(
        rndc_command_arguments,
        capture_output=True,
        text=True,
        timeout=60,
    )
    if completed_rndc_process.returncode != 0:
        return {
            "zone": normalized_zone_name,
            "removed": False,
            "error": completed_rndc_process.stderr.strip() or completed_rndc_process.stdout.strip(),
        }

    candidate_zone_file_names = [
        f"{normalized_zone_name}.zone",
        f"{normalized_zone_name}.db",
        f"{normalized_zone_name}.zone.jnl",
        f"{normalized_zone_name}.db.jnl",
        f"{normalized_zone_name}.zone.signed",
    ]
    deleted_file_paths = []
    for candidate_file_name in candidate_zone_file_names:
        candidate_file_path = resolved_zone_directory / candidate_file_name
        if candidate_file_path.exists():
            candidate_file_path.unlink()
            deleted_file_paths.append(str(candidate_file_path))

    return {
        "zone": normalized_zone_name,
        "view": view_name,
        "removed": True,
        "rndc_output": completed_rndc_process.stdout.strip(),
        "deleted_files": deleted_file_paths,
    }

import os
import requests
from langchain_core.tools import tool

PORKBUN_API_BASE_URL = "https://api.porkbun.com/api/json/v3"


@tool
def register_available_domain(domain_name: str, max_price_usd: float) -> dict:
    porkbun_credentials = {"apikey": os.environ["PORKBUN_API_KEY"], "secretapikey": os.environ["PORKBUN_SECRET_KEY"]}
    availability_response = requests.post(f"{PORKBUN_API_BASE_URL}/domain/checkDomain/{domain_name}", json=porkbun_credentials, timeout=30).json()
    availability_details = availability_response.get("response", {})
    quoted_price_usd = float(availability_details.get("price", 0))
    if availability_details.get("avail") != "yes" or quoted_price_usd > max_price_usd:
        return {"domain": domain_name, "registered": False, "availability": availability_details}
    registration_payload = dict(porkbun_credentials, cost=int(round(quoted_price_usd * 100)), agreeToTerms="yes")
    registration_response = requests.post(f"{PORKBUN_API_BASE_URL}/domain/create/{domain_name}", json=registration_payload, timeout=60).json()
    return {"domain": domain_name, "registered": registration_response.get("status") == "SUCCESS", "price_usd": quoted_price_usd, "result": registration_response}

import dns.resolver
from agents import function_tool


@function_tool
def lookup_dns_records(hostname: str, record_type: str, resolver_address: str = "1.1.1.1") -> dict:
    dns_resolver = dns.resolver.Resolver(configure=False)
    dns_resolver.nameservers = [resolver_address]
    dns_resolver.lifetime = 10.0
    normalized_record_type = record_type.strip().upper()
    try:
        dns_answer = dns_resolver.resolve(hostname, normalized_record_type, raise_on_no_answer=False)
    except dns.resolver.NXDOMAIN:
        return {"hostname": hostname, "type": normalized_record_type, "status": "NXDOMAIN", "records": []}
    record_values = [record_data.to_text() for record_data in dns_answer]
    record_ttl = dns_answer.rrset.ttl if dns_answer.rrset is not None else None
    return {
        "hostname": hostname,
        "type": normalized_record_type,
        "resolver": resolver_address,
        "status": "NOERROR",
        "ttl": record_ttl,
        "records": record_values,
    }
